// JWT Decoder
// Decodes JWT header and payload (does NOT verify signature)

var token = input.get("token");

// Base64 URL decode function using bit shifting
var b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function base64UrlDecode(input) {
    // Convert base64url to base64
    var str = input.replace(/-/g, '+').replace(/_/g, '/');
    // Add padding if needed
    var pad = str.length % 4;
    if (pad) {
        if (pad === 1) throw new Error('Invalid base64 string');
        for (var p = 0; p < 4 - pad; p++) str += '=';
    }

    var output = "";
    var buffer = 0;
    var bits = 0;

    for (var i = 0; i < str.length; i++) {
        var c = str.charAt(i);
        if (c === '=') break;

        var val = b64chars.indexOf(c);
        if (val === -1) continue;

        buffer = (buffer << 6) | val;
        bits += 6;

        if (bits >= 8) {
            bits -= 8;
            output += String.fromCharCode((buffer >> bits) & 0xFF);
        }
    }
    return output;
}

if (!token || token.trim() === "") {
    log.error("JWT token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "JWT token is required");
    output.set("Header", "");
    output.set("Payload", "");
    tags.trigger("error");
} else {
    try {
        token = token.trim();

        // Remove 'Bearer ' prefix if present
        if (token.toLowerCase().indexOf("bearer ") === 0) {
            token = token.substring(7);
        }

        var parts = token.split('.');
        if (parts.length !== 3) {
            throw new Error("Invalid JWT format - expected 3 parts separated by dots");
        }

        var headerJson = base64UrlDecode(parts[0]);
        var payloadJson = base64UrlDecode(parts[1]);

        log.debug("Header JSON: " + headerJson);
        log.debug("Payload JSON: " + payloadJson);

        var header = json.parse(headerJson);
        var payload = json.parse(payloadJson);

        output.set("Header", json.stringify(header));
        output.set("Payload", json.stringify(payload));
        output.set("HeaderObject", header);
        output.set("PayloadObject", payload);

        // Extract common claims
        output.set("Algorithm", header.alg || "");
        output.set("TokenType", header.typ || "");
        output.set("Subject", payload.sub || "");
        output.set("Issuer", payload.iss || "");
        output.set("Audience", payload.aud ? (Array.isArray(payload.aud) ? json.stringify(payload.aud) : payload.aud) : "");

        // Handle expiration
        if (payload.exp) {
            var expDate = new Date(payload.exp * 1000);
            output.set("ExpiresAt", expDate.toISOString());
            output.set("ExpiresAtUnix", payload.exp);
            output.set("IsExpired", Date.now() > payload.exp * 1000);
        } else {
            output.set("ExpiresAt", "");
            output.set("ExpiresAtUnix", 0);
            output.set("IsExpired", false);
        }

        // Issued at
        if (payload.iat) {
            var iatDate = new Date(payload.iat * 1000);
            output.set("IssuedAt", iatDate.toISOString());
        } else {
            output.set("IssuedAt", "");
        }

        output.set("HasErrors", false);
        output.set("ErrorMessage", "");
        log.info("Decoded JWT: alg=" + (header.alg || "unknown") + ", sub=" + (payload.sub || "none"));
        tags.trigger("success");

    } catch (ex) {
        log.error("JWT decode failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", ex.message);
        output.set("Header", "");
        output.set("Payload", "");
        tags.trigger("error");
    }
}
